Both consumers below are memoized. `App` re-renders because of `tick`, while `user` stays `'ann'`. Which render?

```jsx
const Ctx = createContext(null);
const Reader = memo(function Reader() { useContext(Ctx); return null; });
const Other = memo(function Other() { return null; });

function App() {
  const [tick, setTick] = useState(0);
  const user = 'ann';
  const value = useMemo(() => ({ user }), [user]);
  return (
    <Ctx.Provider value={value}>
      <Reader />
      <Other />
    </Ctx.Provider>
  );
}
```

Each `Cell` is memoized, yet every one of 2,000 cells re-renders on each click. What fixes it without changing behaviour?

```jsx
function Grid({ cells }) {
  const [selected, setSelected] = useState(null);
  const select = useCallback((id) => {
    if (selected !== id) setSelected(id);
  }, [selected]);
  return cells.map((c) => (
    <Cell key={c.id} cell={c} isSelected={c.id === selected} onSelect={select} />
  ));
}
```

